84	    /**
85	     * Common street-type abbreviations expanded during address normalization. Keys are the
86	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
87	     * expanded form it is replaced with.
88	     */
89	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
90	        "ST", "STREET",
91	        "RD", "ROAD",
92	        "AVE", "AVENUE");
