160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Override
162	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
163	        validateRequiredFields(ownerFieldsDto);
164	        LocalDate registrationDate = toBusinessDay(
165	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now());
166	        rejectDailyLimitReached(registrationDate);
167	        HttpHeaders headers = new HttpHeaders();
168	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
169	        String address = normalizeAddress(ownerFieldsDto.getAddress());
170	        owner.setAddress(address);
171	        rejectCityAtCapacity(owner.getCity());
172	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
173	            assignHousehold(owner, ownerFieldsDto.getLastName(), address);
174	        } else {
175	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), address);
176	        }
177	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
178	        rejectDuplicateTelephone(telephone);
179	        owner.setTelephone(telephone);
180	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
181	        owner.setRegistrationDate(registrationDate);
182	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
183	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
184	        this.clinicService.saveOwner(owner);
185	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
186	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
187	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
188	        applyBulkSignupWarning(ownerDto);
189	        headers.setLocation(UriComponentsBuilder.newInstance()
190	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
191	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
192	    }
