204	        currentOwner.setLastName(ownerFieldsDto.getLastName());
205	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
206	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
207	        this.clinicService.saveOwner(currentOwner);
208	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
