16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date", columnDefinition = "DATE")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
67	    private Set<Pet> pets;
68	
69	    /**
70	     * Fixed city-to-region lookup backing {@link #getLocality()}. Any city not listed derives
71	     * locality {@code 'UNKNOWN'}.
72	     */
73	    private static final Map<String, String> CITY_REGION = Map.of(
74	        "Sydney", "NSW",
75	        "Melbourne", "VIC",
76	        "Brisbane", "QLD");
77	
78	    public String getAddress() {
79	        return this.address;
80	    }
81	
82	    public void setAddress(String address) {
83	        this.address = address;
84	    }
85	
86	    public String getCity() {
87	        return this.city;
88	    }
89	
90	    public void setCity(String city) {
91	        this.city = city;
92	    }
93	
94	    public String getTelephone() {
95	        return this.telephone;
96	    }
97	
98	    public void setTelephone(String telephone) {
99	        this.telephone = telephone;
100	    }
101	
102	    public String getEmail() {
103	        return this.email;
104	    }
105	
106	    public void setEmail(String email) {
107	        this.email = email;
108	    }
109	
110	    public LocalDate getRegistrationDate() {
111	        return this.registrationDate;
112	    }
113	
114	    public void setRegistrationDate(LocalDate registrationDate) {
115	        this.registrationDate = registrationDate;
116	    }
117	
118	    public String getCustomerCode() {
119	        return this.customerCode;
120	    }
121	
122	    public void setCustomerCode(String customerCode) {
123	        this.customerCode = customerCode;
124	    }
125	
126	    public String getHouseholdId() {
127	        return this.householdId;
128	    }
129	
130	    public void setHouseholdId(String householdId) {
131	        this.householdId = householdId;
132	    }
133	
134	    public Integer getNamesakeCount() {
135	        return this.namesakeCount;
136	    }
137	
138	    public void setNamesakeCount(Integer namesakeCount) {
139	        this.namesakeCount = namesakeCount;
140	    }
141	
142	    /**
143	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
144	     */
145	    @Transient
146	    public String getDisplayName() {
147	        return this.getLastName() + ", " + this.getFirstName();
148	    }
149	
150	    /**
151	     * The owner's initials: the upper-cased first letters of the first and last name,
152	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
153	     */
154	    @Transient
155	    public String getInitials() {
156	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
157	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
158	    }
159	
160	    /**
161	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
162	     * the last two digits of the registration date year (e.g. {@code 'SMI-0007-M26'}). Derived from
163	     * the owner's own fields; {@code null} until both the customer code and registration date are set.
164	     */
165	    @Transient
166	    public String getMembershipNumber() {
167	        if (this.customerCode == null || this.registrationDate == null) {
168	            return null;
169	        }
170	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
171	    }
172	
173	    /**
174	     * The owner's numeric membership level, from 1 to 3. It starts at 1, gains 1 when the owner has
175	     * an email address, gains 1 when the owner is unique (namesakeCount is 0), and is capped at 3
176	     * (level 4 is reserved for tenure). The inputs are the owner's own fields.
177	     */
178	    @Transient
179	    public Integer getMembershipLevel() {
180	        int level = 1;
181	        boolean hasEmail = this.email != null && !this.email.isBlank();
182	        if (hasEmail) {
183	            level++;
184	        }
185	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
186	        if (unique) {
187	            level++;
188	        }
189	        return Math.min(level, 3);
190	    }
191	
192	    /**
193	     * The owner's locality: the canonical region derived from the city via the fixed city-to-region
194	     * table ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or {@code 'UNKNOWN'}
195	     * when the city is not in the table.
196	     */
197	    @Transient
198	    public String getLocality() {
199	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
200	    }
201	
202	    protected Set<Pet> getPetsInternal() {
203	        if (this.pets == null) {
204	            this.pets = new HashSet<>();
205	        }
206	        return this.pets;
207	    }
208	
209	    protected void setPetsInternal(Set<Pet> pets) {
210	        this.pets = pets;
211	    }
212	
213	    public List<Pet> getPets() {
214	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
215	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
216	        return Collections.unmodifiableList(sortedPets);
217	    }
218	
219	    public void setPets(List<Pet> pets) {
220	        this.pets = new HashSet<>(pets);
221	    }
222	
223	    public void addPet(Pet pet) {
224	        getPetsInternal().add(pet);
225	        pet.setOwner(this);
226	    }
227	
228	    /**
229	     * Return the Pet with the given name, or null if none found for this Owner.
230	     *
231	     * @param name to test
232	     * @return true if pet name is already in use
233	     */
234	    public Pet getPet(String name) {
235	        return getPet(name, false);
236	    }
237	
238	    /**
239	     * Return the Pet with the given name, or null if none found for this Owner.
240	     *
241	     * @param name to test
242	     * @return true if pet name is already in use
243	     */
244	    public Pet getPet(String name, boolean ignoreNew) {
245	        name = name.toLowerCase();
246	        for (Pet pet : getPetsInternal()) {
247	            if (!ignoreNew || !pet.isNew()) {
248	                String compName = pet.getName();
249	                compName = compName.toLowerCase();
250	                if (compName.equals(name)) {
251	                    return pet;
252	                }
253	            }
254	        }
255	        return null;
256	    }
257	
258	    public Pet getPet(Integer petId) {
259	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
260	    }
261	
262	    @Override
263	    public String toString() {
264	        return new ToStringCreator(this)
265	
266	            .append("id", this.getId())
267	            .append("new", this.isNew())
268	            .append("lastName", this.getLastName())
269	            .append("firstName", this.getFirstName())
270	            .append("address", this.address)
271	            .append("city", this.city)
272	            .append("telephone", this.telephone)
273	            .toString();
274	    }
275	}
